peg'rule'D1_S :: PegRt.P (Peg'Store peg's) peg's ((()), [PegRt.Child])
peg'rule'D1_S =
  PegRt.memoLR peg'memo'D1_S "D1_S"
    (PegRt.node syntaxKindD1_S (PegRt.choice
      [ do { (x1, peg'k0) <- PegRt.label "x1" (peg'rule'D1_A)
          ; PegRt.touch x1
          ; PegPrelude.pure ((), peg'k0)
          }
      , do { (_, peg'k1) <- PegRt.plain (PegRt.lit "c" "'c'")
          ; (_, peg'k2) <- peg'rule'D1_A
          ; (_, peg'k3) <- peg'rule'D1_B
          ; PegPrelude.pure ((), PegPrelude.concat [peg'k1, peg'k2, peg'k3])
          }
      ]))

peg'rule'D1_A :: PegRt.P (Peg'Store peg's) peg's ((()), [PegRt.Child])
peg'rule'D1_A =
  PegRt.memoLR peg'memo'D1_A "D1_A"
    (PegRt.node syntaxKindD1_A (PegRt.choice
      [ do { (x1, peg'k0) <- PegRt.label "x1" (peg'rule'D1_B)
          ; PegRt.touch x1
          ; (_, peg'k2) <- (PegRt.many1S) (PegRt.choice [do { (_, peg'k1) <- peg'rule'D1_B
          ; PegPrelude.pure ((), peg'k1)
          }])
          ; PegPrelude.pure ((), PegPrelude.concat [peg'k0, peg'k2])
          }
      , do { (_, peg'k18) <- PegRt.choice [do { (_, peg'k10) <- PegRt.choice [do { (_, peg'k7) <- PegRt.choice [do { (_, peg'k3) <- PegRt.plain (PegRt.lit "c" "'c'")
          ; PegPrelude.pure ((), peg'k3)
          }, do { (_, peg'k4) <- peg'rule'D1_S
          ; (_, peg'k5) <- PegRt.plain (PegRt.lit "ab" "'ab'")
          ; (_, peg'k6) <- PegRt.plain (PegRt.lit "b" "'b'")
          ; PegPrelude.pure ((), PegPrelude.concat [peg'k4, peg'k5, peg'k6])
          }]
          ; (_, peg'k8) <- PegRt.plain (PegRt.lit "a" "'a'")
          ; PegPrelude.pure ((), PegPrelude.concat [peg'k7, peg'k8])
          }, do { (_, peg'k9) <- PegRt.plain (PegRt.cls [('a', 'a'), ('b', 'b')] "[ab]")
          ; PegPrelude.pure ((), peg'k9)
          }]
          ; PegPrelude.pure ((), peg'k10)
          }, do { (_, peg'k11) <- PegRt.plain (PegRt.lit "a" "'a'")
          ; (_, peg'k16) <- PegRt.choice [do { (_, peg'k14) <- PegRt.choice [do { (_, peg'k12) <- peg'rule'D1_B
          ; (_, peg'k13) <- PegRt.labeledS "D1_l" PegPrelude.Nothing (peg'rule'D1_S)
          ; PegPrelude.pure ((), PegPrelude.concat [peg'k12, peg'k13])
          }]
          ; (_, peg'k15) <- PegRt.labeledS "D1_l" PegPrelude.Nothing (PegRt.plain (PegRt.lit "ab" "'ab'"))
          ; PegPrelude.pure ((), PegPrelude.concat [peg'k14, peg'k15])
          }]
          ; (_, peg'k17) <- PegRt.plain (PegRt.lit "a" "'a'")
          ; PegPrelude.pure ((), PegPrelude.concat [peg'k11, peg'k16, peg'k17])
          }]
          ; (x2, peg'k19) <- PegRt.label "x2" (peg'rule'D1_A)
          ; PegRt.touch x2
          ; PegPrelude.pure ((), PegPrelude.concat [peg'k18, peg'k19])
          }
      ]))

peg'rule'D1_B :: PegRt.P (Peg'Store peg's) peg's ((()), [PegRt.Child])
peg'rule'D1_B =
  PegRt.nomemo "D1_B"
    (PegRt.choice
      [ do { (_, peg'k0) <- PegRt.plain (PegRt.lit "a" "'a'")
          ; (x2, peg'k1) <- PegRt.label "x2" (peg'rule'D1_S)
          ; PegRt.touch x2
          ; PegPrelude.pure ((), PegPrelude.concat [peg'k0, peg'k1])
          }
      , do { (_, peg'k2) <- PegRt.plain (PegRt.lit "a" "'a'")
          ; PegPrelude.pure ((), peg'k2)
          }
      ])

peg'rule'D2_S :: PegRt.P (Peg'Store peg's) peg's ((()), [PegRt.Child])
peg'rule'D2_S =
  PegRt.memoLR peg'memo'D2_S "D2_S"
    (PegRt.node syntaxKindD2_S (PegRt.choice
      [ do { (_, peg'k3) <- PegRt.choice [do { (_, peg'k1) <- PegRt.choice [do { (_, peg'k0) <- PegRt.labeledMessageS "D2_l" "missing D2_" (PegPrelude.Just (PegRt.voidS peg'rule'D2_R)) (PegRt.voidS (PegRt.plain (PegRt.lit "b" "'b'")))
